export type ItemsPerPage = 25 | 50 | 100;

export type PaginationProps = {
	count: number;
	current?: number;
	divider?: boolean;
	itemsPerPage?: ItemsPerPage;
	itemsPerPageLabel?: (context: { count: number; current: number; itemsPerPage: ItemsPerPage }) => string;
	showingResultsLabel?: (context: { count: number; current: number; itemsPerPage: ItemsPerPage }) => string;
	onSetCurrent?: Dispatch<SetStateAction<number>>;
	onSetItemsPerPage?: Dispatch<SetStateAction<ItemsPerPage>>;
} & HTMLAttributes<HTMLElement>;

const defaultItemsPerPageLabel = () => 'Items per page:';

const defaultShowingResultsLabel = ({ count, current, itemsPerPage }: { count: number; current: number; itemsPerPage: ItemsPerPage }) =>
	`Showing results ${current + 1} - ${Math.min(current + itemsPerPage, count)} of ${count}`;

const itemsPerPageOptions = [25, 50, 100] as const;

const Pagination = ({
	count,
	current = 0,
	itemsPerPage = 25,
	itemsPerPageLabel = defaultItemsPerPageLabel,
	showingResultsLabel = defaultShowingResultsLabel,
	onSetItemsPerPage,
	onSetCurrent,
	divider,
	...props
}: PaginationProps) => {
	const paginationResultLabelId = useId();
	const itemsPerPageLabelId = useId();

	const hasItemsPerPageSelection = itemsPerPageOptions.length > 1;
	const currentPage = Math.floor(current / itemsPerPage);
	const pages = Math.ceil(count / itemsPerPage);
	const displayedPages = useMemo(() => {
		if (pages <= 7) {
			// 0 1 2 3 4 5 6
			return Array.from({ length: pages }, (_, i) => i);
		}

		if (currentPage < 5) {
			// 0 1 2 3 4 ... N
			return [0, 1, 2, 3, 4, '⋯', pages - 1];
		}

		if (currentPage > pages - 5) {
			// 0 ... N-4 N-3 N-2 N-1 N
			return [0, '⋯', pages - 5, pages - 4, pages - 3, pages - 2, pages - 1];
		}

		// 0 ... x-1 x x-2 ... N
		return [0, '⋯', currentPage - 1, currentPage, currentPage + 1, '⋯', pages - 1];
	}, [pages, currentPage]);

	const renderingContext = { count, pages, current, currentPage, itemsPerPage };

	const handleSetItemsPerPageLinkClick = (itemsPerPageOption: ItemsPerPage) => () => {
		onSetItemsPerPage?.(itemsPerPageOption);
	};

	const handleSetPageLinkClick = (page: number) => () => {
		onSetCurrent?.(page * itemsPerPage);
	};

	// Handlers travel in spread attributes: zero-runtime rejects a render element that carries them itself
	const itemsPerPageButton = (itemsPerPageOption: ItemsPerPage) => ({
		'tabIndex': itemsPerPage === itemsPerPageOption ? -1 : 0,
		'disabled': itemsPerPage === itemsPerPageOption,
		'aria-label': `Show ${itemsPerPageOption} items per page`,
		'onClick': handleSetItemsPerPageLinkClick(itemsPerPageOption),
	});

	const pageButton = (page: number) => ({
		'disabled': currentPage === page,
		'aria-label': `Page ${page + 1}`,
		'onClick': handleSetPageLinkClick(page),
	});

	const stepButton = (label: string, inactive: boolean, page: number) => ({
		'disabled': inactive,
		'aria-label': label,
		'onClick': handleSetPageLinkClick(page),
	});

	// The caller's attributes go on the element `render` names: zero-runtime rejects spreads on a frame
	const attributes = { 'aria-label': 'Pagination Navigation', ...props };

	return (
		<PaginationFrame
			render={<nav {...attributes} />}
			divider={Boolean(divider)}
			className={['rcx-box rcx-box--full rcx-pagination', divider && 'rcx-pagination--divider'].filter(Boolean).join(' ')}
		>
			{hasItemsPerPageSelection && (
				<LeftFrame className='rcx-pagination__left'>
					<LabelFrame id={itemsPerPageLabelId} className='rcx-pagination__label'>
						{itemsPerPageLabel(renderingContext)}
					</LabelFrame>
					<ListFrame aria-labelledby={itemsPerPageLabelId} className='rcx-box rcx-box--full rcx-pagination__list'>
						{itemsPerPageOptions.map((itemsPerPageOption) => (
							<ListItemFrame key={itemsPerPageOption} className='rcx-pagination__list-item'>
								<LinkFrame
									render={<button {...itemsPerPageButton(itemsPerPageOption)} />}
									current={itemsPerPage === itemsPerPageOption}
									className='rcx-box rcx-box--full rcx-pagination__link'
								>
									{itemsPerPageOption}
								</LinkFrame>
							</ListItemFrame>
						))}
					</ListFrame>
				</LeftFrame>
			)}
			<RightFrame className='rcx-pagination__right'>
				<LabelFrame id={paginationResultLabelId} className='rcx-pagination__label'>
					{showingResultsLabel(renderingContext)}
				</LabelFrame>
				<ListFrame aria-labelledby={paginationResultLabelId} className='rcx-box rcx-box--full rcx-pagination__list'>
					<ListItemFrame className='rcx-pagination__list-item'>
						<StepFrame
							render={<button {...stepButton('Previous page', currentPage === 0, currentPage - 1)} />}
							inactive={currentPage === 0}
							className='rcx-box rcx-box--full rcx-pagination__back'
						>
							<Chevron left size='x16' />
						</StepFrame>
					</ListItemFrame>
					{displayedPages.map((page, i) => (
						<ListItemFrame key={i} className='rcx-pagination__list-item'>
							{page === '⋯' ? (
								'⋯'
							) : (
								<LinkFrame
									render={<button {...pageButton(Number(page))} />}
									current={currentPage === page}
									className='rcx-box rcx-box--full rcx-pagination__link'
								>
									{Number(page) + 1}
								</LinkFrame>
							)}
						</ListItemFrame>
					))}
					<ListItemFrame className='rcx-pagination__list-item'>
						<StepFrame
							render={<button {...stepButton('Next page', currentPage === pages - 1, currentPage + 1)} />}
							inactive={currentPage === pages - 1}
							className='rcx-box rcx-box--full rcx-pagination__forward'
						>
							<Chevron right size='x16' />
						</StepFrame>
					</ListItemFrame>
				</ListFrame>
			</RightFrame>
		</PaginationFrame>
	);
};

export default Pagination;
